33	/** ADR 0016/0019: only when AI processing is on and the Round meets N. */
34	export const shouldRequestThemes = (result: RoundResult, aiProcessing: boolean): boolean =>
35	  aiProcessing &&
36	  result.meetsMinimumGroupSize &&
37	  !result.delayed &&
38	  (result.status === "closed" || result.status === "ready" || result.status === "shared");
