40	/**
41	 * Builds the only thing sent to the model. Comments come from the stored Result (already redacted
42	 * at store time, ADR 0009), in the stored (shuffled) order: index i = result.comments[i].
43	 * Action titles are redacted here with `redact(title, roster)`.
44	 */
45	export const buildThemesInput = (
46	  result: RoundResult,
47	  openActionTitles: ReadonlyArray<string>,
48	  roster: Roster,
49	): AiInput => {
50	  const questionPositions = new Map(result.questions.map((q) => [q.questionVersionId, q.position]));
51	  return {
52	    questions: result.questions.map((q) => ({
53	      position: q.position,
54	      text: q.text,
55	      dimension: q.dimension,
56	      score: q.meetsMinimumGroupSize ? q.score : null,
57	      change: q.change?.change ?? null,
58	      largerThanUsual: q.change?.highlight?.isLargerThanUsual ?? false,
59	    })),
60	    dimensions: result.dimensions
61	      .filter((d) => d.meetsMinimumGroupSize)
62	      .map((d) => ({
63	        dimension: d.dimension,
64	        score: d.score,
65	        change: d.change?.change ?? null,
66	        largerThanUsual: d.change?.highlight?.isLargerThanUsual ?? false,
67	      })),
68	    comments: result.meetsMinimumGroupSize
69	      ? result.comments.map((c) => ({
70	          questionPosition: questionPositions.get(c.questionVersionId) ?? -1,
71	          text: RedactedText.make(c.text),
72	        }))
73	      : [],
74	    actions: openActionTitles.flatMap((title) => {
75	      const redacted = redact(title, roster);
76	      return redacted.trim() === "" ? [] : [{ title: RedactedText.make(redacted) }];
77	    }),
78	  };
79	};
