83	/**
84	 * Strict JSON schema sent as response_format (ADR 0015). Every object: type object, all properties
85	 * required, additionalProperties false. Limits are stated in descriptions and enforced in
86	 * `checkThemesReply`, because provider strict mode rejects maxItems, minimum and minLength.
87	 */
88	export const themesJsonSchema: Record<string, unknown> = {
89	  type: "object",
