100	        properties: {
101	          label: { type: "string", description: "A short label of 6 words or fewer." },
102	          sentence: {
103	            type: "string",
104	            description: "One neutral sentence that paraphrases the theme. Never quote a comment.",
105	          },
106	          supportingCommentIndexes: {
107	            type: "array",
108	            description: "Indexes, counted from 0, of the comments that support this theme.",
109	            items: { type: "integer" },
110	          },
111	        },
112	      },
113	    },
114	    guide: {
115	      type: "object",
116	      additionalProperties: false,
117	      required: ["whatStoodOut", "whatPeopleRaised", "actionsToCheckOn", "questions"],
118	      properties: {
119	        whatStoodOut: {
120	          type: "array",
121	          description: "What stood out in the scores and changes, especially larger-than-usual changes.",
