123	        },
124	        whatPeopleRaised: {
125	          type: "array",
126	          description: "What people raised in the comments, paraphrased. Never quote.",
127	          items: { type: "string" },
128	        },
129	        actionsToCheckOn: {
130	          type: "array",
131	          description: "Only titles from the given open Actions. Empty when there are none.",
132	          items: { type: "string" },
133	        },
134	        questions: {
135	          type: "array",
