144	export const themesInstructions = [
145	  "You write the Comment themes and the discussion guide for one Round of a Team's pulse check.",
146	  "You receive the Round's anonymous data as JSON: questions with scores and changes, dimensions with scores and changes (largerThanUsual marks a change that is bigger than usual), comments indexed from 0, and the titles of open Actions.",
147	  `Write at most ${MAX_THEMES} Comment themes. Each has a short label of 6 words or fewer and one neutral sentence, plus the indexes of the comments that support it.`,
148	  `Only write a theme that at least ${MIN_SUPPORTING_COMMENTS} comments support.`,
149	  `Paraphrase. Never quote a comment and never reuse ${QUOTE_RUN_WORDS} or more consecutive words from a comment.`,
150	  "Never say or guess who wrote a comment, never name anyone, and never mention anything that is not in the input.",
151	  "Keep the wording neutral. Never advise punishing or praising an individual.",
152	  "The discussion guide has four lists:",
153	  "- whatStoodOut: what stood out in the scores and changes, especially the larger-than-usual ones.",
154	  "- whatPeopleRaised: what people raised in the comments, paraphrased.",
155	  "- actionsToCheckOn: only titles from the given open Actions; empty when there are none.",
156	  "- questions: at most 3 open questions the Lead can ask the Team.",
157	  "The same rules apply to the guide: paraphrase, never quote, and never say who said what.",
158	  "With no comments, return no themes and build the guide from the scores and Actions.",
159	  "Reply only with JSON that matches the schema.",
160	].join("\n");
161	
162	export const themesRequest = (input: AiInput): AiRequest => ({
163	  instructions: themesInstructions,
164	  input,
165	  schemaName: THEMES_SCHEMA_NAME,
166	  schema: themesJsonSchema,
167	  maxTokens: 2000,
168	});
