170	/**
171	 * Lowercased words of `text` with diacritics removed, split on anything that is not a letter or a
172	 * number. Word-based, so scripts written without spaces are not covered (SurveyBeat ships English and
173	 * German, ADR 0018).
174	 */
175	const wordsOf = (text: string): ReadonlyArray<string> =>
176	  text
177	    .normalize("NFKD")
178	    .replace(/\p{M}/gu, "")
179	    .toLowerCase()
180	    .split(/[^\p{L}\p{N}]+/u)
181	    .filter((word) => word.length > 0);
182	
183	/** Every window of QUOTE_RUN_WORDS consecutive words, joined by a space. */
184	const runsOf = (text: string): Set<string> => {
185	  const words = wordsOf(text);
186	  const runs = new Set<string>();
187	  for (let i = 0; i + QUOTE_RUN_WORDS <= words.length; i++) {
188	    runs.add(words.slice(i, i + QUOTE_RUN_WORDS).join(" "));
189	  }
190	  return runs;
191	};
192	
193	/** True when `text` repeats QUOTE_RUN_WORDS or more consecutive words of any comment (ADR 0016). */
194	export const repeatsCommentWords = (text: string, comments: ReadonlyArray<string>): boolean => {
195	  const commentRuns = new Set(comments.flatMap((comment) => [...runsOf(comment)]));
196	  return [...runsOf(text)].some((run) => commentRuns.has(run));
197	};
198	
199	export class ThemesReplyInvalid extends Data.TaggedError("ThemesReplyInvalid") {}
200	
201	const ReplyEnvelope = Schema.Struct({
202	  themes: Schema.Array(Schema.Unknown),
203	  guide: Schema.optionalKey(Schema.Unknown),
204	});
205	
206	const ThemeReply = Schema.Struct({
207	  label: Schema.String.pipe(Schema.check(Schema.isMinLength(1))),
208	  sentence: Schema.String.pipe(Schema.check(Schema.isMinLength(1))),
209	  supportingCommentIndexes: Schema.Array(Schema.Int),
210	});
211	
212	const decodeEnvelope = Schema.decodeUnknownOption(ReplyEnvelope);
213	const decodeThemeReply = Schema.decodeUnknownOption(ThemeReply);
214	const decodeGuide = Schema.decodeUnknownOption(DiscussionGuide);
215	
216	/**
217	 * ADR 0016/0019 checks on the model's reply. Fails only when the top level is not an object with a
218	 * `themes` array. Otherwise the reply is cleaned, never repaired:
219	 * - only the first MAX_THEMES entries are considered; an entry that does not decode is dropped;
220	 * - supportingComments counts distinct in-range comment indexes; fewer than 2 drops the theme;
221	 * - a label or sentence that repeats a 6-word run of any comment drops the theme;
222	 * - the guide must decode as DiscussionGuide, and no string in it may repeat a 6-word run; otherwise
223	 *   the whole guide is null.
224	 */
225	export const checkThemesReply = (
226	  reply: unknown,
227	  comments: ReadonlyArray<string>,
228	): Effect.Effect<StoredThemes, ThemesReplyInvalid> => {
229	  const envelope = Option.getOrNull(decodeEnvelope(reply));
230	  if (envelope === null) {
231	    return Effect.fail(new ThemesReplyInvalid());
232	  }
233	
234	  const themes = envelope.themes.slice(0, MAX_THEMES).flatMap((entry) => {
235	    const decoded = Option.getOrNull(decodeThemeReply(entry));
236	    if (decoded === null) return [];
237	    const supporters = new Set(
238	      decoded.supportingCommentIndexes.filter((index) => index >= 0 && index < comments.length),
239	    ).size;
240	    if (supporters < MIN_SUPPORTING_COMMENTS) return [];
241	    // Checked together too, so a quote split between the label and the sentence is caught.
242	    if (repeatsCommentWords(`${decoded.label} ${decoded.sentence}`, comments)) {
243	      return [];
244	    }
245	    return [{ label: decoded.label, sentence: decoded.sentence, supportingComments: supporters }];
246	  });
247	
248	  const guide = Option.getOrNull(decodeGuide(envelope.guide));
249	  const guideRepeats =
250	    guide === null ||
251	    [...guide.whatStoodOut, ...guide.whatPeopleRaised, ...guide.actionsToCheckOn, ...guide.questions].some(
252	      (text) => repeatsCommentWords(text, comments),
253	    );
254	
255	  return Effect.succeed({ themes, guide: guideRepeats ? null : guide });
256	};
257	
258	/**
259	 * Backoff for the k-th failed attempt (k >= 1): min(5 min * 2^(k-1), 4 h). Returns the next due
260	 * time, or null when it would fall after requestedAt + 24 h (give up).
261	 */
262	export const nextThemesAttemptAt = (
263	  requestedAt: number,
264	  failedAttempts: number,
265	  now: number,
266	): number | null => {
267	  const k = Math.max(1, failedAttempts);
268	  const gap = Math.min(FIRST_RETRY_GAP_MS * 2 ** (k - 1), MAX_RETRY_GAP_MS);
269	  const dueAt = now + gap;
270	  return dueAt > requestedAt + THEMES_RETRY_WINDOW_MS ? null : dueAt;
271	};
272	
273	export type ThemesJobDecision =
274	  | { readonly _tag: "Store"; readonly themes: StoredThemes }
275	  | { readonly _tag: "RetryAt"; readonly dueAt: number; readonly attempts: number }
276	  | { readonly _tag: "GiveUp" };
277	
278	/**
279	 * One attempt of the Round's single themes call. AiNotConfigured gives up, since nothing will change.
280	 * AiRejected, AiUnavailable and ThemesReplyInvalid retry at the backoff time, or give up once the
281	 * window is over. Never logs the reply or an error body.
282	 */
283	export const runThemesAttempt = (params: {
284	  readonly input: AiInput;
285	  readonly requestedAt: number;
286	  readonly attempts: number;
287	  readonly now: number;
288	}): Effect.Effect<ThemesJobDecision, never, AiClient> => {
289	  const comments = params.input.comments.map((c) => c.text);
290	  const retry = (): ThemesJobDecision => {
291	    const failedAttempts = params.attempts + 1;
292	    const dueAt = nextThemesAttemptAt(params.requestedAt, failedAttempts, params.now);
293	    return dueAt === null ? { _tag: "GiveUp" } : { _tag: "RetryAt", dueAt, attempts: failedAttempts };
294	  };
295	
296	  return AiClient.use((client) => client.complete(themesRequest(params.input))).pipe(
297	    Effect.flatMap((reply) => checkThemesReply(reply, comments)),
298	    Effect.map((themes): ThemesJobDecision => ({ _tag: "Store", themes })),
299	    Effect.catchTags({
300	      AiNotConfigured: (): Effect.Effect<ThemesJobDecision> => Effect.succeed({ _tag: "GiveUp" }),
301	      AiRejected: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
302	      AiUnavailable: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
303	      ThemesReplyInvalid: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
304	    }),
305	  );
306	};
