308	/**
309	 * The Result as one viewer may see it (ADR 0004, 0016, 0019). Single source of truth used by the
310	 * Organization object and the privacy tests.
311	 *
312	 * The Round's current row decides the status and the Review window end, not the stored payload. Until
313	 * the Round is Shared, only the Lead sees its Result (the Review window, see Issue #106).
314	 */
315	export const viewRoundResult = (params: {
316	  readonly stored: RoundResult;
317	  readonly organizationN: number;
318	  readonly isLead: boolean;
319	  readonly themes: RoundThemesRecord | null;
320	  readonly round: { readonly status: RoundStatus; readonly reviewEndsAt: number | null };
321	}): RoundResult => {
322	  // Theme fields come only from the themes record, never from whatever the stored Result carries.
323	  const {
324	    themes: _themes,
325	    themesStatus: _themesStatus,
326	    discussionGuide: _discussionGuide,
327	    reviewEndsAt: _reviewEndsAt,
328	    ...r
329	  } = enforceEffectiveNOnResult(params.stored, params.organizationN);
330	  const status = params.round.status;
331	  const reviewEnds =
332	    status === "ready" && params.round.reviewEndsAt !== null
333	      ? { reviewEndsAt: params.round.reviewEndsAt }
334	      : {};
335	
336	  if (!params.isLead && (status === "closed" || status === "ready")) {
337	    return {
338	      ...r,
339	      ...reviewEnds,
340	      status,
341	      questions: [],
342	      dimensions: [],
343	      comments: [],
344	      themesStatus: "notRequested",
345	      themes: [],
346	    };
347	  }
348	
349	  const shown: RoundResult = { ...r, ...reviewEnds, status, comments: params.isLead ? r.comments : [] };
350	
351	  const hidden = (themesStatus: "notRequested" | "preparing" | "unavailable"): RoundResult => ({
352	    ...shown,
353	    themesStatus,
354	    themes: [],
355	    ...(params.isLead ? { discussionGuide: null } : {}),
356	  });
357	
358	  const record = params.themes;
359	  const closed = status === "closed" || status === "ready" || status === "shared";
360	  if (!closed || !r.meetsMinimumGroupSize || record === null) return hidden("notRequested");
361	
362	  switch (record.status) {
363	    case "pending":
364	      return hidden("preparing");
365	    case "failed":
366	      return hidden("unavailable");
367	    case "ready":
368	      if (!params.isLead) {
369	        return {
370	          ...shown,
371	          themesStatus: "ready",
372	          themes: record.themes.themes.map(({ label, sentence }) => ({ label, sentence })),
373	        };
374	      }
375	      return {
376	        ...shown,
377	        themesStatus: "ready",
378	        themes: record.themes.themes,
379	        discussionGuide: record.themes.guide,
380	      };
381	  }
382	};
