11	} from "@surveybeat/domain";
12	import * as Clock from "effect/Clock";
13	import * as Effect from "effect/Effect";
14	import { HttpServerRequest } from "effect/http/HttpServerRequest";
15	import * as HttpServerResponse from "effect/http/HttpServerResponse";
16	import type { Organizations } from "./EmailDelivery.ts";
