18	export const REVIEW_TEST_ROUTE = "/__test/review";
19	
20	const DAY_MS = 86_400_000;
21	
22	type OrganizationStub = ReturnType<Organizations["getByName"]>;
23	
24	/** Sets the Pulse's Review window in days, keeping its other settings (test stages only). */
25	export const setReviewWindowDays = (
26	  organization: OrganizationStub,
27	  admin: PersonId,
28	  teamId: TeamId,
29	  pulseId: PulseId,
30	  days: number,
31	  now: number,
32	) =>
33	  Effect.gen(function* () {
34	    const detail = yield* organization.viewPulse(admin, teamId, pulseId);
35	    if (detail._tag !== "Viewed") return;
36	    yield* organization.runPulseCommand(
37	      admin,
38	      {
39	        _tag: "UpdatePulseSettings",
40	        teamId,
41	        pulseId,
42	        settings: { ...detail.value.settings, reviewWindowDays: days },
43	      },
44	      now,
45	    );
46	  });
47	
48	/** The people and Pulse of one scenario: a Lead, two members, and an admin, with one Pulse in one Team. */
49	interface People {
50	  readonly organization: OrganizationStub;
51	  readonly admin: PersonId;
52	  readonly lead: PersonId;
53	  readonly member: PersonId;
54	  readonly otherMember: PersonId;
55	  readonly teamId: TeamId;
56	  readonly pulseId: PulseId;
57	}
58	
59	/** The People, and one Round of their Pulse (the one the scenario drives). */
60	interface Cast extends People {
61	  readonly roundId: RoundId;
62	  readonly closeJobId: string;
63	  readonly closeDue: number;
64	}
65	
66	/**
67	 * One Organization with a Lead, two members, and N = 3, AI processing off, and one Pulse with the Review window
68	 * `windowDays`. Creating the Pulse schedules its first Round.
69	 */
70	const setUpPulse = (organizations: Organizations, label: string, windowDays: number, now: number) =>
71	  Effect.gen(function* () {
72	    const organizationId = `review-${label}`;
73	    const organization = organizations.getByName(organizationId);
74	    const admin = PersonId.make(`admin-${label}`);
75	    const lead = PersonId.make(`lead-${label}`);
76	    const member = PersonId.make(`member-${label}`);
77	    const otherMember = PersonId.make(`other-${label}`);
78	    const teamId = TeamId.make(`team-${label}`);
79	    const pulseId = PulseId.make(`pulse-${label}`);
80	    const signInUrl = "https://app.surveybeat.app/";
81	
82	    yield* organization.createWithAdmin(
83	      organizationId,
84	      "Acme",
85	      admin,
86	      `admin-${label}@example.com`,
87	      `user_admin_${label}`,
88	    );
89	    yield* organization.runDirectoryCommand(
90	      admin,
91	      { _tag: "UpdateSettings", minimumGroupSize: 3, aiProcessing: false },
92	      now,
93	    );
94	    yield* organization.runDirectoryCommand(
95	      admin,
96	      {
97	        _tag: "CreateTeam",
98	        teamId,
99	        name: "Engineering",
100	        timeZone: TimeZone.make("Europe/Berlin"),
101	        lead: {
102	          email: EmailAddress.make(`lead-${label}@example.com`),
103	          personId: lead,
104	          membershipId: MembershipId.make(`membership-lead-${label}`),
105	          signInUrl,
106	        },
107	      },
108	      now,
109	    );
110	    yield* organization.runDirectoryCommand(
111	      admin,
112	      {
113	        _tag: "AddMember",
114	        teamId,
115	        role: "member",
116	        member: {
117	          email: EmailAddress.make(`member-${label}@example.com`),
118	          personId: member,
119	          membershipId: MembershipId.make(`membership-member-${label}`),
120	          signInUrl,
121	        },
122	      },
123	      now,
124	    );
125	    yield* organization.runDirectoryCommand(
126	      admin,
127	      {
128	        _tag: "AddMember",
129	        teamId,
130	        role: "member",
131	        member: {
132	          email: EmailAddress.make(`other-${label}@example.com`),
133	          personId: otherMember,
134	          membershipId: MembershipId.make(`membership-other-${label}`),
135	          signInUrl,
136	        },
137	      },
138	      now,
139	    );
140	    yield* organization.runPulseCommand(admin, { _tag: "CreatePulse", pulseId, teamId }, now);
141	    yield* setReviewWindowDays(organization, admin, teamId, pulseId, windowDays, now);
142	
143	    const people: People = { organization, admin, lead, member, otherMember, teamId, pulseId };
144	    return people;
145	  });
146	
147	/** The Round of a Pulse with `status`, or the first one listed when none is given (the Pulse's first Round). */
148	const roundOf = (people: People, status: string | null) =>
149	  Effect.gen(function* () {
150	    const listed = yield* people.organization.viewRounds(people.admin, people.teamId, people.pulseId);
151	    const rounds = listed._tag === "Viewed" ? listed.value.rounds : [];
152	    const match = status === null ? rounds[0] : rounds.find((round) => round.status === status);
153	    if (match === undefined) return yield* Effect.die(new Error(`no ${status ?? "first"} round`));
154	    return RoundId.make(match.id);
155	  });
156	
157	/**
158	 * Opens a Round, has the three people answer (so it meets N), and returns its close job. Each answer is keyed
159	 * by `tag`, so two Rounds of one Pulse never share an edit id.
160	 */
161	const openAndAnswer = (people: People, roundId: RoundId, tag: string) =>
162	  Effect.gen(function* () {
163	    const { organization, lead, member, otherMember } = people;
164	    const openJob = (yield* organization.getJobsForRound(roundId)).find((job) => job.type === "open");
165	    if (openJob === undefined) return yield* Effect.die(new Error("no open job"));
166	    yield* organization.runScheduleJob(openJob.id, openJob.due_at);
167	
168	    const context = yield* organization.getSubmissionRoundContext(roundId, lead);
169	    const questions = context?.questions ?? [];
170	    const firstRating = questions.find((question) => question.type._tag === "Rating");
171	    for (const [index, person] of [lead, member, otherMember].entries()) {
172	      yield* organization.recordFirstAnswer(
173	        roundId,
174	        person,
175	        `edit-${tag}-${index}`,
176	        questions.map((question) => ({
177	          questionVersionId: question.id,
178	          value: question.type._tag === "Rating" ? 4 : null,
179	          comment: question.id === firstRating?.id ? `Comment ${index} on ${tag}` : null,
180	        })),
181	      );
182	    }
183	
184	    const closeJob = (yield* organization.getJobsForRound(roundId)).find((job) => job.type === "close");
185	    if (closeJob === undefined) return yield* Effect.die(new Error("no close job"));
186	    const cast: Cast = { ...people, roundId, closeJobId: closeJob.id, closeDue: closeJob.due_at };
187	    return cast;
188	  });
189	
190	/** A Pulse's first Round, opened and answered, not yet closed. */
191	const openedRound = (organizations: Organizations, label: string, windowDays: number, now: number) =>
192	  Effect.gen(function* () {
193	    const people = yield* setUpPulse(organizations, label, windowDays, now);
194	    return yield* openAndAnswer(people, yield* roundOf(people, null), label);
195	  });
196	
197	/** A Pulse's first Round, opened, answered, and closed: Ready with a window above 0, Shared with 0. */
198	const closedRound = (organizations: Organizations, label: string, windowDays: number, now: number) =>
199	  Effect.gen(function* () {
200	    const cast = yield* openedRound(organizations, label, windowDays, now);
201	    yield* cast.organization.runScheduleJob(cast.closeJobId, cast.closeDue);
202	    return cast;
203	  });
204	
205	/** The Round's jobs of one type, as the schedule table holds them. */
206	const jobsOfType = (cast: Cast, type: string) =>
207	  Effect.map(cast.organization.getJobsForRound(cast.roundId), (jobs) =>
208	    jobs.filter((job) => job.type === type),
209	  );
210	
211	/** Who has a results-ready email scheduled for this Round, by role name, sorted. */
212	const resultsReadyFor = (cast: Cast) =>
213	  Effect.map(cast.organization.getJobsForRound(cast.roundId), (jobs) => {
214	    const prefix = `results-ready-${cast.roundId}-`;
215	    const roleOf = (personId: string) =>
216	      personId === cast.lead
217	        ? "lead"
218	        : personId === cast.member
219	          ? "member"
220	          : personId === cast.otherMember
221	            ? "other"
222	            : personId;
223	    return jobs
224	      .filter((job) => job.type === "send" && job.id.startsWith(prefix))
225	      .map((job) => roleOf(job.id.slice(prefix.length)))
226	      .sort();
227	  });
228	
229	const viewOf = (cast: Cast, person: PersonId) =>
230	  Effect.map(cast.organization.viewResults(person, cast.teamId, cast.roundId), (viewed): RoundResult | null =>
231	    viewed._tag === "Viewed" ? viewed.value : null,
232	  );
233	
234	const hasNote = (cast: Cast, person: PersonId) =>
235	  Effect.map(
236	    cast.organization.viewRoundNote(person, cast.teamId, cast.roundId),
237	    (viewed) => viewed._tag === "Viewed" && viewed.value.note !== null,
238	  );
239	
240	const statusOf = (cast: Cast) =>
241	  Effect.map(cast.organization.getRound(cast.roundId), (round) => round?.status ?? null);
242	
243	/** "Accepted", or the rejection's tag. */
244	const commandOutcome = (result: RoundCommandResult) =>
245	  result._tag === "Accepted" ? "Accepted" : result.rejection._tag;
246	
247	const shareCommand = (cast: Cast, actor: PersonId, now: number) =>
248	  Effect.map(
249	    cast.organization.runRoundCommand(
250	      actor,
251	      { _tag: "ShareResults", teamId: cast.teamId, roundId: cast.roundId },
252	      now,
253	    ),
254	    commandOutcome,
255	  );
256	
257	/** What a viewer sees of a Result: its status, which Result sections it carries, and whether its Review window end is the share job's due time. */
258	const viewSummary = (view: RoundResult | null, shareDue: number | undefined) => ({
259	  status: view?.status ?? null,
260	  seesQuestions: (view?.questions.length ?? 0) > 0,
261	  seesDimensions: (view?.dimensions.length ?? 0) > 0,
262	  seesComments: (view?.comments.length ?? 0) > 0,
263	  seesGuideKey: view !== null && "discussionGuide" in view,
264	  reviewEndsAtIsShareDue: shareDue !== undefined && view?.reviewEndsAt === shareDue,
265	});
266	
267	/**
268	 * Test stages only (`isTestStage`): the Review window (issue 106) on a real Organization Durable Object and
269	 * local workerd. Three Organizations, each with a Lead, two members, N = 3, and AI off:
270	 * - window 0: the Round is shared at close (R1 behaviour): no share job, every Person gets a results-ready email.
271	 * - window 3, shared by hand: the Round is Ready at close; the share job is due three days later; only the
272	 *   Lead has a results-ready email; members see no Result data; the Lead shares it twice (both Accepted);
273	 *   a member and an admin are Forbidden; afterwards the share job is cancelled and the members have emails.
274	 * - window 3, shared by the window's end: changing the Pulse's window after close does not move the share job;
275	 *   running the share job twice and then the due jobs shares the Round once.
276	 */
277	export const reviewTestRoutes = (organizations: Organizations) =>
278	  Effect.gen(function* () {
279	    const request = yield* HttpServerRequest;
280	    const run = new URL(request.url, "http://localhost").searchParams.get("run") ?? "";
281	    const now = yield* Clock.currentTimeMillis;
282	
283	    // Window 0: shared at once.
284	    const zero = yield* closedRound(organizations, `${run}-zero`, 0, now);
285	    const zeroView = yield* viewOf(zero, zero.member);
286	    const zeroSummary = {
287	      roundStatus: yield* statusOf(zero),
288	      shareJobs: (yield* jobsOfType(zero, "share")).length,
289	      resultsReadyFor: yield* resultsReadyFor(zero),
290	      memberSeesQuestions: (zeroView?.questions.length ?? 0) > 0,
291	    };
292	
293	    // Window 3, shared by the Lead.
294	    const manual = yield* closedRound(organizations, `${run}-manual`, 3, now);
295	    const manualShare = (yield* jobsOfType(manual, "share"))[0];
296	    if (manualShare === undefined) return yield* Effect.die(new Error("no share job"));
297	    // Read before any share command runs, so the summary shows the Round as it was at close.
298	    const roundBefore = yield* statusOf(manual);
299	    const resultsReadyBefore = yield* resultsReadyFor(manual);
300	    const leadBefore = yield* viewOf(manual, manual.lead);
301	    const memberBefore = yield* viewOf(manual, manual.member);
302	    // The Lead's Note: the Lead sees it during the Review window, a member only once the Round is Shared.
303	    yield* manual.organization.saveRoundNote(
304	      manual.lead,
305	      manual.teamId,
306	      manual.roundId,
307	      "Talk on Monday",
308	      now,
309	    );
310	    const leadSeesNoteBefore = yield* hasNote(manual, manual.lead);
311	    const memberSeesNoteBefore = yield* hasNote(manual, manual.member);
312	    const memberCommand = yield* shareCommand(manual, manual.member, now);
313	    const adminCommand = yield* shareCommand(manual, manual.admin, now);
314	    const leadFirstShare = yield* shareCommand(manual, manual.lead, manual.closeDue);
315	    const leadSecondShare = yield* shareCommand(manual, manual.lead, manual.closeDue);
316	    const leadAfter = yield* viewOf(manual, manual.lead);
317	    const memberAfter = yield* viewOf(manual, manual.member);
318	    const memberSeesNoteAfter = yield* hasNote(manual, manual.member);
319	    const manualSummary = {
320	      roundStatus: roundBefore,
321	      shareJobDueDays: (manualShare.due_at - manual.closeDue) / DAY_MS,
322	      shareJobStatus: manualShare.status,
323	      resultsReadyBefore,
324	      leadView: viewSummary(leadBefore, manualShare.due_at),
325	      memberView: viewSummary(memberBefore, manualShare.due_at),
326	      memberCommand,
327	      adminCommand,
328	      leadFirstShare,
329	      leadSecondShare,
330	      roundStatusAfterShare: yield* statusOf(manual),
331	      shareJobStatusAfterShare: (yield* jobsOfType(manual, "share"))[0]?.status ?? null,
332	      resultsReadyAfter: yield* resultsReadyFor(manual),
333	      leadViewAfter: viewSummary(leadAfter, manualShare.due_at),
334	      memberViewAfter: viewSummary(memberAfter, manualShare.due_at),
335	      leadSeesNoteBefore,
336	      memberSeesNoteBefore,
337	      memberSeesNoteAfter,
338	    };
339	
340	    // Window 3, shared when the window ends: a later change to the Pulse does not move the share job.
341	    const auto = yield* closedRound(organizations, `${run}-auto`, 3, now);
342	    // Changed at the close, the Organization's clock: an earlier `now` would re-plan the next Round into the past.
343	    yield* setReviewWindowDays(auto.organization, auto.admin, auto.teamId, auto.pulseId, 7, auto.closeDue);
344	    const autoShare = (yield* jobsOfType(auto, "share"))[0];
345	    if (autoShare === undefined) return yield* Effect.die(new Error("no share job"));
346	    const autoBefore = {
347	      roundStatus: yield* statusOf(auto),
348	      shareJobDueDays: (autoShare.due_at - auto.closeDue) / DAY_MS,
349	    };
350	    yield* auto.organization.runScheduleJob(autoShare.id, autoShare.due_at);
351	    yield* auto.organization.runScheduleJob(autoShare.id, autoShare.due_at);
352	    yield* auto.organization.runDueJobs(autoShare.due_at);
353	    const autoView = yield* viewOf(auto, auto.member);
354	    const autoSummary = {
355	      ...autoBefore,
356	      roundStatusAfterWindow: yield* statusOf(auto),
357	      shareJobStatusAfterWindow: (yield* jobsOfType(auto, "share"))[0]?.status ?? null,
358	      resultsReadyAfter: yield* resultsReadyFor(auto),
359	      memberSeesQuestionsAfter: (autoView?.questions.length ?? 0) > 0,
360	    };
361	
362	    // Cascade: Round A is Ready, then the Pulse's next Round B is also Ready. The Lead shares B, which shares A too.
363	    const cascade = yield* closedRound(organizations, `${run}-cascade`, 7, now);
364	    const roundA = cascade.roundId;
365	    const roundB = yield* roundOf(cascade, "scheduled");
366	    const closingB = yield* openAndAnswer(cascade, roundB, `${run}-cascade-b`);
367	    yield* cascade.organization.runScheduleJob(closingB.closeJobId, closingB.closeDue);
368	    const roundBCast: Cast = {
369	      ...cascade,
370	      roundId: roundB,
371	      closeJobId: closingB.closeJobId,
372	      closeDue: closingB.closeDue,
373	    };
374	    const sharedB = yield* shareCommand(roundBCast, cascade.lead, closingB.closeDue);
375	    const roundSummary = (cast: Cast) =>
376	      Effect.gen(function* () {
377	        return {
378	          roundStatus: yield* statusOf(cast),
379	          shareJobStatus: (yield* jobsOfType(cast, "share"))[0]?.status ?? null,
380	          resultsReadyFor: yield* resultsReadyFor(cast),
381	        };
382	      });
383	    const cascadeSummary = {
384	      shareCommand: sharedB,
385	      roundA: yield* roundSummary({ ...cascade, roundId: roundA }),
386	      roundB: yield* roundSummary(roundBCast),
387	    };
388	
389	    // Close early: a Lead closes an Open Round of a window-2 Pulse; the share job is due two days after closing.
390	    const early = yield* openedRound(organizations, `${run}-early`, 2, now);
391	    const openedRoundRecord = yield* early.organization.getRound(early.roundId);
392	    const openedAt = openedRoundRecord?.openedAt ?? null;
393	    if (openedAt === null) return yield* Effect.die(new Error("round not open"));
394	    const closeEarly = yield* early.organization.runRoundCommand(
395	      early.lead,
396	      { _tag: "CloseRoundEarly", teamId: early.teamId, roundId: early.roundId },
397	      openedAt + DAY_MS,
398	    );
399	    const earlyRound = yield* early.organization.getRound(early.roundId);
400	    const earlyShare = (yield* jobsOfType(early, "share"))[0];
401	    const closeEarlySummary = {
402	      command: commandOutcome(closeEarly),
403	      roundStatus: earlyRound?.status ?? null,
404	      shareJobStatus: earlyShare?.status ?? null,
405	      shareJobDueDays:
406	        earlyShare === undefined || earlyRound?.closedAt === null || earlyRound?.closedAt === undefined
407	          ? null
408	          : (earlyShare.due_at - earlyRound.closedAt) / DAY_MS,
409	    };
410	
411	    return yield* HttpServerResponse.json({
412	      zero: zeroSummary,
413	      manual: manualSummary,
414	      auto: autoSummary,
415	      cascade: cascadeSummary,
416	      closeEarly: closeEarlySummary,
417	    });
418	  });
